insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('7dec74dc-2b56-5201-a48c-87b6ed7276b9', 'full-mock-1', 'Full Mock 1', 'Complete digital SAT practice test', 'full_mock', 'both', null, 'mixed', 'Four timed parts: two Reading and Writing modules of 27 questions and two Math modules of 22 questions. 98 questions, 2 hours 14 minutes of testing time.', 1) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', '7dec74dc-2b56-5201-a48c-87b6ed7276b9', 1, 'Reading and Writing — Module 1', 'rw', 1920) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c7dffade-2d39-5880-aa73-2a3b09d575b0', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'When the botanist Ynes Mexia began collecting plants in 1925, she was fifty-five years old and had no formal training beyond a handful of university courses. Colleagues expected a brief hobby. Instead, over thirteen years she gathered more than 145,000 specimens, including some five hundred species new to science. Her output was, by any measure, prodigious.', 'As used in the text, what does the word "prodigious" most nearly mean?', '[{"key":"A","text":"Enormous"},{"key":"B","text":"Careless"},{"key":"C","text":"Unexpected"},{"key":"D","text":"Puzzling"}]'::jsonb, 'A', null, 'The sentence summarises figures — 145,000 specimens and 500 new species — so the word must describe sheer quantity, and ''enormous'' captures that. ''Unexpected'' is tempting because colleagues were surprised, but the surprise is stated separately; the final sentence rates the output itself, not its predictability.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c328c698-25b7-5033-a99d-7fda5676817b', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 2, 'craft_structure', 'text_structure_purpose', 'easy', 'mc', 'Sea otters eat enormous quantities of sea urchins. Urchins, in turn, graze on kelp. Where otters were hunted out in the nineteenth century, urchin populations exploded and kelp forests collapsed into bare rock. Where otters returned, kelp returned with them. The otter is small, but the forest depends on it.', 'Which choice best describes the overall structure of the text?', '[{"key":"A","text":"It poses a question and then rejects two possible answers to it."},{"key":"B","text":"It traces a chain of ecological cause and effect and then states its implication."},{"key":"C","text":"It compares two habitats that responded differently to the same disturbance."},{"key":"D","text":"It presents a widely held belief and then supplies evidence against it."}]'::jsonb, 'B', null, 'The text moves otters → urchins → kelp, then reports what happened when the first link was removed and restored, closing with the implication that a small animal supports the forest. Choice C is tempting because two situations are mentioned, but they are the same habitat before and after otter loss, not two different habitats.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5e13e3b0-b626-5a0a-a3da-20a5c9de0e3c', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 3, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Critics initially dismissed the composer Florence Price''s symphonies as derivative, hearing in them only echoes of Dvořák. Later scholars have argued that this reading is _______: the spirituals and juba rhythms woven through her scoring are structural, not decorative, and they organise the music in ways Dvořák never attempted.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"exhaustive"},{"key":"B","text":"reductive"},{"key":"C","text":"speculative"},{"key":"D","text":"unflattering"}]'::jsonb, 'B', null, 'The colon explains that the earlier reading missed structural features of Price''s music, so the word must mean ''oversimplifying'' — ''reductive''. ''Unflattering'' is true of the criticism but describes its tone rather than its analytical failure, which is what the second half of the sentence documents.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c65120fb-caeb-5e8f-a7d0-da01318c199a', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 4, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'The following is adapted from a 1908 novel. Mrs. Aldingham had a gift for the small remark that ended a conversation. ''How brave of you to wear that,'' she said, and the room, which had been noisy, found other things to look at. Her daughter had learned to read the weather of these silences before she learned to read print.', 'What is the main purpose of the final sentence of the text?', '[{"key":"A","text":"To explain why Mrs. Aldingham speaks as she does"},{"key":"B","text":"To indicate how routine and formative the mother''s behaviour is for the daughter"},{"key":"C","text":"To suggest that the daughter is unusually slow to learn to read"},{"key":"D","text":"To contrast the daughter''s manners with her mother''s"}]'::jsonb, 'B', null, 'Saying the daughter learned to read these silences before print signals that the pattern was constant enough to shape her early. Choice C misreads the comparison, which is about the order in which two skills were acquired, not about any deficiency in reading.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('54dfbbe3-abcc-5cfc-af3c-12cb726bd597', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 5, 'craft_structure', 'cross_text_connections', 'medium', 'mc', 'Text 1: Urban rewilding projects, which let city parkland grow unmanaged, have been criticised as an abdication of care. Tidy planting, the argument runs, is what makes a park feel safe and welcoming to the widest range of residents.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('22867ebc-fb5d-5ba1-a204-9d6d715a572b', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 6, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Archaeologists once treated the absence of grave goods at the site as evidence of poverty. Recent work has _______ that inference: at several comparable settlements, wealthy households deliberately buried their dead without objects, reserving valuables for the living.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"confirmed"},{"key":"B","text":"unsettled"},{"key":"C","text":"publicised"},{"key":"D","text":"restated"}]'::jsonb, 'B', null, 'The colon supplies a counterexample showing that absent grave goods need not indicate poverty, so the recent work destabilises the old inference — ''unsettled''. ''Confirmed'' reverses the logic, and ''restated'' would require the new work to repeat rather than challenge the earlier claim.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6c8547f5-b4e2-58cc-a15c-8c022aa15b4c', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 7, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: The economist argues that remote work redistributes opportunity: a software job once tied to two coastal cities can now be held from anywhere, lifting incomes in regions long bypassed by growth.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a3eeccaf-80b0-52e9-afc7-b3e5ae7e8f04', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 8, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'In 1943 the mathematician wrote to her editor that the proof was ''finished, in the sense that a house is finished when the roof is on and the rain still comes through the ceiling.'' She published two years later.', 'What is the main rhetorical effect of the simile in the text?', '[{"key":"A","text":"It conveys that the proof was structurally complete but not yet sound in detail."},{"key":"B","text":"It emphasises how quickly the mathematician worked once she had an outline."},{"key":"C","text":"It suggests that the mathematician regarded the proof as a failure."},{"key":"D","text":"It implies that the editor had unreasonable expectations of her."}]'::jsonb, 'A', null, 'A roofed house that still leaks has its overall structure in place while remaining defective in particulars, which maps onto a complete argument with unresolved gaps — and the two-year delay before publication supports this. Choice C overstates it: an unfinished house is not a demolished one, and the work was eventually published.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fee5ebb0-2f89-5028-a73a-4830027eda09', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 9, 'information_ideas', 'central_ideas_details', 'easy', 'mc', 'Honeybees communicate the location of food through a waggle dance whose angle encodes direction relative to the sun and whose duration encodes distance. Because the sun moves across the sky, a bee that has waited inside the hive must adjust the angle of her dance to account for the time elapsed — and she does.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Honeybees prefer to forage when the sun is directly overhead."},{"key":"B","text":"The waggle dance conveys direction and distance, and bees correct it for the sun''s movement."},{"key":"C","text":"Bees that wait inside the hive lose track of where food is located."},{"key":"D","text":"The duration of the waggle dance is more informative than its angle."}]'::jsonb, 'B', null, 'The text defines the two things the dance encodes and then adds that bees compensate for solar movement. Choice C directly contradicts the final clause, which states that the waiting bee does make the adjustment.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7289ef7f-51f5-587f-acb4-1f9bfbc23a98', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 10, 'information_ideas', 'evidence_textual', 'easy', 'mc', 'A student claims that the Roman road network was designed primarily for military movement rather than trade.', 'Which finding, if true, would most directly support the student''s claim?', '[{"key":"A","text":"Roman roads were paved with locally quarried stone wherever possible."},{"key":"B","text":"Road construction consistently followed, rather than preceded, the arrival of legions in a province."},{"key":"C","text":"Merchants'' accounts frequently mention travelling on Roman roads."},{"key":"D","text":"Many Roman roads remained in use for centuries after the empire fell."}]'::jsonb, 'B', null, 'If roads were built after legions arrived, construction tracked military campaigns, which is exactly the priority the student asserts. Choice C is evidence for the rival claim, and choices A and D concern materials and longevity, which are silent on purpose.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('43480676-7519-5b94-a45c-87becbe4c828', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 11, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'The novelist Nella Larsen published only two novels and a handful of stories before leaving literature for nursing. Critics have often framed this as a silence. Larsen''s letters suggest something narrower: after a plagiarism accusation she considered and dismissed as baseless, she stopped seeking publication, not writing.', 'According to the text, what do Larsen''s letters indicate about her departure from literature?', '[{"key":"A","text":"She continued to write but withdrew from the process of publishing."},{"key":"B","text":"She accepted that the plagiarism accusation against her was justified."},{"key":"C","text":"She found nursing more satisfying than writing had been."},{"key":"D","text":"She had planned to write only two novels from the start."}]'::jsonb, 'A', null, 'The final clause draws precisely this distinction: she stopped seeking publication, not writing. Choice B reverses the text, which says she dismissed the accusation as baseless.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5feb23ab-f878-5c8d-a4f3-431c25ba803b', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 12, 'information_ideas', 'evidence_quantitative', 'medium', 'mc', 'A team measured germination rates for a native wildflower at four soil temperatures. At 10°C, 18 percent of seeds germinated; at 15°C, 44 percent; at 20°C, 71 percent; and at 25°C, 39 percent. The researchers concluded that the species has an intermediate thermal optimum for germination.', 'Which choice most effectively uses data from the text to support the researchers'' conclusion?', '[{"key":"A","text":"Germination rose steadily with temperature, from 18 percent at 10°C to 71 percent at 20°C."},{"key":"B","text":"Germination peaked at 20°C (71 percent) and fell to 39 percent at the warmer 25°C."},{"key":"C","text":"Fewer than half of all seeds germinated at 10°C and 15°C."},{"key":"D","text":"Germination at 25°C (39 percent) was more than double the rate at 10°C."}]'::jsonb, 'B', null, 'An intermediate optimum requires a rise and then a fall, so the evidence must include both the 20°C peak and the drop at 25°C. Choice A shows only the rising half, which would equally fit a species that simply prefers heat.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('78e0e677-ab6b-5cb5-ad1a-61ab6362d438', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 13, 'information_ideas', 'inferences', 'medium', 'mc', 'Deep-sea anglerfish live where prey is so scarce that an individual may encounter a meal only a few times a year. Their stomachs distend to hold prey larger than themselves, and their metabolic rates are among the lowest measured in vertebrates of comparable size. These traits suggest that, for the anglerfish, _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"hunting speed is the decisive factor in survival."},{"key":"B","text":"the main challenge is surviving long intervals between meals rather than finding abundant food."},{"key":"C","text":"competition with other anglerfish limits population growth."},{"key":"D","text":"body size is unrelated to the amount of prey consumed."}]'::jsonb, 'B', null, 'Both traits described — a stomach that banks an oversized meal and a very low metabolic rate — are adaptations for waiting, which points to scarcity over time as the central problem. Choice A is unsupported: nothing in the text concerns speed, and low metabolism argues against it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('51230913-030a-5cc3-a7b4-785713f26485', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 14, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'Historians disagree about why sixteenth-century Antwerp overtook Bruges as the commercial capital of the Low Countries. One school emphasises the silting of the Zwin channel, which cut Bruges off from deep water. Another argues that Antwerp''s success was institutional: its fairs offered creditor protections that Bruges''s guild courts did not.', 'Which quotation from a historical record, if authentic, would most weaken the institutional explanation?', '[{"key":"A","text":"''The Antwerp fairs were crowded beyond memory in the year 1520.''"},{"key":"B","text":"''Merchants of Lucca removed to Antwerp only after their galleys could no longer reach Bruges at any tide.''"},{"key":"C","text":"''The magistrates of Antwerp confirmed the privileges of foreign creditors in a charter of 1515.''"},{"key":"D","text":"''Bruges''s guilds refused to hear suits brought by foreign merchants.''"}]'::jsonb, 'B', null, 'The institutional account says merchants moved for legal protections; a record showing they moved only once navigation failed attributes the shift to silting instead. Choice D would strengthen the institutional account by confirming that Bruges''s courts were closed to foreigners.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('add43640-33c2-5905-a3b3-ef527c8c37c1', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 15, 'information_ideas', 'inferences', 'hard', 'mc', 'Tree-ring records from the Colorado Plateau show that the twelfth-century drought was neither the driest nor the hottest of the last two millennia, yet it coincides with the most extensive settlement abandonment in the region''s archaeological record. Researchers note that the drought was, however, the longest.', 'Which choice most logically completes the text?', '[{"key":"A","text":"Tree-ring records are unreliable indicators of past temperature."},{"key":"B","text":"Settlement abandonment in the region was unrelated to climate."},{"key":"C","text":"Duration may matter more than severity in determining whether communities can absorb a drought."},{"key":"D","text":"The twelfth-century population of the plateau was smaller than previously estimated."}]'::jsonb, 'C', null, 'The paragraph pointedly rules out severity and heat as distinguishing features while highlighting length, so the inference is that persistence, not intensity, drove abandonment. Choice B ignores the coincidence the passage treats as significant.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f5fde2dc-657a-5a73-a5d7-b1bcc99623cb', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 16, 'standard_conventions', 'boundaries', 'easy', 'mc', 'The lighthouse at Cape Byron was automated in 1989 _______ the keeper''s cottages remained standing and now house researchers.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", but"},{"key":"B","text":", and it"},{"key":"C","text":"; and"},{"key":"D","text":" but,"}]'::jsonb, 'A', null, 'Two independent clauses joined by the coordinating conjunction ''but'' require a comma before the conjunction. Choice B adds a redundant subject ''it'' that leaves ''the keeper''s cottages'' without a verb structure that fits, and choice D misplaces the comma after the conjunction.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('46a67b0d-0e99-5ae1-a22f-afc454910f80', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 17, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'Each of the six volcanic islands in the chain _______ a distinct population of finches found nowhere else.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"support"},{"key":"B","text":"have supported"},{"key":"C","text":"supports"},{"key":"D","text":"are supporting"}]'::jsonb, 'C', null, 'The subject is ''Each'', which is singular, so the verb must be ''supports''; the plural noun ''islands'' sits inside a prepositional phrase and cannot control the verb. Choice B is also plural in form and shifts the tense without cause.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4b817f7f-1836-5652-a0c9-30e2ca851713', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 18, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Working entirely at night to avoid the heat, the excavation team uncovered a mosaic floor _______ its central panel showed a hunting scene in nine colours of stone.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":": "},{"key":"C","text":", and "},{"key":"D","text":"; and, "}]'::jsonb, 'B', null, 'The second clause specifies what was found, so a colon correctly introduces the elaboration after a complete independent clause. Choice A creates a comma splice between two independent clauses, and choice D''s comma after ''and'' is unidiomatic.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4aed0614-fec6-55cb-a46d-e898f7cf2da2', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 19, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'The curator argued that the vase, along with the two bronze mirrors recovered from the same chamber, _______ almost certainly imported rather than produced locally.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"were"},{"key":"B","text":"have been"},{"key":"C","text":"are being"},{"key":"D","text":"was"}]'::jsonb, 'D', null, 'The subject is the singular ''vase''; the phrase ''along with...'' is parenthetical and does not make the subject plural, so ''was'' is correct. Choice A is the trap: the nearby plural ''mirrors'' pulls the ear toward a plural verb.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('64fd0b2f-fe18-5fb5-a356-e15c66bb7c7d', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 20, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Marie Tharp''s 1957 map of the Atlantic seafloor revealed a continuous rift valley running down the ridge _______ a feature her colleague initially dismissed as ''girl talk.''', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":". "},{"key":"C","text":"; "},{"key":"D","text":" and "}]'::jsonb, 'A', null, '''A feature her colleague initially dismissed'' is a noun phrase in apposition to the rift valley, and an appositive is set off with a comma. A period or semicolon would leave that phrase as a fragment because it contains no main verb of its own.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('42ee4e13-d6bb-58da-a77a-09fc50e1c7cd', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 21, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'Having sequenced the genomes of forty ancient horse specimens, _______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"the domestication date was pushed back by nearly a millennium."},{"key":"B","text":"the team pushed the domestication date back by nearly a millennium."},{"key":"C","text":"nearly a millennium was added to the domestication date by the team."},{"key":"D","text":"there was a shift of nearly a millennium in the domestication date."}]'::jsonb, 'B', null, 'The opening participial phrase must modify whoever did the sequencing, so the main clause has to begin with ''the team''. The other options leave the modifier dangling, attaching the sequencing to a date, a millennium, or nothing at all.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8b9afc09-2fd3-5666-ae6c-489d45593641', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 22, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The archive holds letters from three writers who never met in person _______ Rabindranath Tagore, who wrote from Bengal; Romain Rolland, who wrote from Switzerland; and Ocampo, who wrote from Buenos Aires.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":": "},{"key":"C","text":"; "},{"key":"D","text":", and "}]'::jsonb, 'B', null, 'A complete clause precedes a list that names its items, which is exactly the job of a colon; the items themselves are already separated by semicolons because each contains a comma. A comma before the list would be too weak, and a semicolon would wrongly signal a second independent clause.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('14a78e0f-bf00-50f8-acf6-5d73540fa05b', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 23, 'expression_ideas', 'transitions', 'easy', 'mc', 'Cast iron conducts heat unevenly, producing hot spots that can scorch delicate sauces. _______ its thickness lets it hold a steady temperature once heated, which is why it browns meat so well.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Therefore,"},{"key":"B","text":"However,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"For instance,"}]'::jsonb, 'B', null, 'The first sentence names a drawback and the second names a compensating strength, so a contrastive transition is required. ''Therefore'' would wrongly present the steady temperature as a consequence of uneven conduction.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3cf8c5ad-b57a-526c-a27c-b378b2234859', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 24, 'expression_ideas', 'transitions', 'medium', 'mc', 'Salt marshes trap sediment, and as sea levels rise slowly the marsh surface can build upward at a comparable rate. _______ where the rise outpaces sediment supply, the marsh drowns and converts to open water.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Beyond that,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"In other words,"},{"key":"D","text":"Where possible,"}]'::jsonb, 'A', null, 'The second sentence introduces the case that lies past the limit described in the first, and ''Beyond that'' marks that boundary. ''Consequently'' is wrong because drowning is not a result of successful upward growth — it is what happens when growth fails.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8a85a43c-3cd9-5bfc-a6d6-43e5f13424b3', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 25, 'expression_ideas', 'rhetorical_synthesis', 'medium', 'mc', 'While researching, a student took these notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0b71dea7-9a32-5078-a359-8b14c5b704ec', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 26, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching, a student took these notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('78401e68-fc7d-5541-a8f2-0b03e8075f80', '2e4cbbec-1a66-5cb8-a585-ccb3c0ad527b', 27, 'expression_ideas', 'transitions', 'hard', 'mc', 'Economists had long assumed that consumers respond to a price rise by buying less of a good. Studies of staple foods among very low-income households complicate that picture: when the price of a cheap staple rises, some households buy more of it, cutting the costlier foods that had supplemented it. _______ the demand curve for such a good can slope upward over a limited range.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"In effect,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"Admittedly,"}]'::jsonb, 'B', null, 'The last sentence restates the described behaviour in formal economic terms rather than adding a new or opposing point, which is what ''In effect'' signals. ''Nevertheless'' and ''By contrast'' would falsely mark the conclusion as a reversal of the evidence that supports it.') on conflict (id) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('0a789449-0fd0-5581-a548-d3f35c5f13c4', '7dec74dc-2b56-5201-a48c-87b6ed7276b9', 2, 'Reading and Writing — Module 2', 'rw', 1920) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('acc56b3c-6773-5702-ab6c-b9067966918d', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'The first printed maps of the Pacific were assembled from reports by sailors who had seen only fragments of coastline. Cartographers filled the gaps with _______ guesses, drawing continents where none existed and omitting islands that did.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"confident"},{"key":"B","text":"reluctant"},{"key":"C","text":"measured"},{"key":"D","text":"borrowed"}]'::jsonb, 'A', null, 'The examples that follow — drawing whole continents that do not exist — describe guessing done boldly, so ''confident'' fits. ''Measured'' would suggest restraint, which the invented continents contradict.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2964fe17-3e41-561e-a04a-2de41390d052', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 2, 'craft_structure', 'words_in_context', 'easy', 'mc', 'Reviewers praised the choreographer''s new work for its economy: no gesture was repeated, no dancer stood idle, and the whole piece ran nineteen minutes.', 'As used in the text, what does the word "economy" most nearly mean?', '[{"key":"A","text":"Low production cost"},{"key":"B","text":"Absence of waste"},{"key":"C","text":"Financial system"},{"key":"D","text":"Commercial appeal"}]'::jsonb, 'B', null, 'The colon lists features of efficiency — nothing repeated, nobody idle, a short running time — which defines economy as the absence of waste. ''Low production cost'' borrows the everyday money sense that the examples do not support.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('626aabe9-9c63-56b1-ad1e-bf2d8033ddc6', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 3, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'Most descriptions of the water cycle begin with evaporation from the ocean. This is convenient but arbitrary: the cycle has no starting point, and a raindrop that falls on a forest may be returned to the air by a leaf within hours, never reaching a river at all.', 'What is the main purpose of the text?', '[{"key":"A","text":"To argue that a familiar way of presenting a process misrepresents how it works"},{"key":"B","text":"To explain how transpiration differs from evaporation"},{"key":"C","text":"To criticise scientists for neglecting forests in climate models"},{"key":"D","text":"To describe the path of a single raindrop in detail"}]'::jsonb, 'A', null, 'The text names the conventional starting point and then explains why treating it as a starting point is misleading. Choice B is tempting because the leaf detail involves transpiration, but that detail serves the argument rather than being the point of the passage.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('597c9c1f-517b-5451-aa63-4b372ab90cc2', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 4, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'The following is adapted from a short story. Ojo checked the till three times before locking up, though he had counted it correctly the first time and knew it. The habit had followed him from a job he had left eleven years earlier, where a shortfall of four hundred naira had cost a colleague her position.', 'What is the main purpose of the second sentence?', '[{"key":"A","text":"To reveal that Ojo has previously been accused of theft"},{"key":"B","text":"To explain the origin of a behaviour the first sentence presents as excessive"},{"key":"C","text":"To establish that Ojo is poor at arithmetic"},{"key":"D","text":"To contrast Ojo''s caution with his colleague''s carelessness"}]'::jsonb, 'B', null, 'The first sentence shows an unnecessary triple check; the second supplies the past event that produced the habit. Choice A misidentifies who was affected — the colleague lost her job, and Ojo is never accused.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('bc6496e2-81f3-58ee-a202-658729ca86c9', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 5, 'craft_structure', 'cross_text_connections', 'medium', 'mc', 'Text 1: Museums that return looted artefacts risk emptying their collections and depriving global audiences of access to the world''s heritage.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d8675af8-e98e-58e0-a448-d6d25fda231c', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 6, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: The linguist maintains that children acquire grammar so rapidly, and on such fragmentary input, that much of its structure must be innate.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('93f9108b-a7ea-5f03-a1b4-41f50f6455a4', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 7, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Early reviewers found the poet''s late work austere to the point of coldness. Read alongside her letters, however, the same poems appear _______: the plainness is the discipline of someone who distrusted her own facility for ornament.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"indulgent"},{"key":"B","text":"effortless"},{"key":"C","text":"deliberate"},{"key":"D","text":"derivative"}]'::jsonb, 'C', null, 'The colon explains the plainness as a discipline adopted against a natural talent for ornament, which makes it chosen — ''deliberate''. ''Effortless'' is the opposite of what discipline implies and would undercut the contrast with ''facility''.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b45bfefc-ebff-5716-a885-4b5d90f0b36f', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 8, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'A physicist once described turbulence as the last great unsolved problem of classical physics. The remark is quoted so often that it has acquired the authority of a verdict. It is worth remembering that it was made in a lecture, offhand, and that the speaker spent none of his career working on the problem.', 'What is the main purpose of the final sentence?', '[{"key":"A","text":"To identify the physicist who made the remark"},{"key":"B","text":"To undercut the weight the remark has come to carry"},{"key":"C","text":"To argue that turbulence has now been solved"},{"key":"D","text":"To explain why turbulence is difficult to model"}]'::jsonb, 'B', null, 'By noting that the line was offhand and made by someone who never studied turbulence, the sentence deflates the ''authority of a verdict'' described just before. Choice C goes further than the text, which questions the quotation''s standing rather than the problem''s status.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('051e64d3-0b3c-5a3c-a233-3e9df52932c7', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 9, 'information_ideas', 'central_ideas_details', 'easy', 'mc', 'Fungi in the genus Ophiocordyceps infect ants and alter their behaviour, driving them to climb vegetation and clamp onto a leaf vein before dying. The height and humidity at that spot happen to be close to optimal for the fungus to fruit — but poor for the ant colony''s usual foraging routes.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Ant colonies avoid vegetation that is high and humid."},{"key":"B","text":"The fungus manipulates infected ants into dying in a place that suits the fungus."},{"key":"C","text":"Ophiocordyceps infections are usually survivable for ants."},{"key":"D","text":"Humidity is the main factor limiting fungal growth."}]'::jsonb, 'B', null, 'The passage pairs the altered behaviour with the observation that the final location is optimal for the fungus, which is the point. Choice D overstates one detail; humidity is mentioned as part of the favourable spot, not as the limiting factor generally.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('201f4bf8-d3fe-59c9-a761-488f8af64a85', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 10, 'information_ideas', 'evidence_quantitative', 'easy', 'mc', 'A city compared cycling rates on four corridors one year after adding protected bike lanes to two of them. On the two protected corridors, daily cycling trips rose from 620 to 1,410 and from 480 to 1,090. On the two unchanged corridors, trips moved from 550 to 575 and from 700 to 690.', 'Which choice best describes data in the text that support the conclusion that protected lanes increased cycling?', '[{"key":"A","text":"Cycling more than doubled on both protected corridors while remaining nearly flat on both unchanged ones."},{"key":"B","text":"Cycling rose on three of the four corridors studied."},{"key":"C","text":"The busiest corridor before the change was also the busiest afterward."},{"key":"D","text":"Total cycling trips across all four corridors increased."}]'::jsonb, 'A', null, 'The comparison that isolates the effect of the lanes is the contrast between the doubled protected corridors and the flat control corridors. Choice D reports an aggregate that the unchanged corridors could not explain and does not separate treatment from control.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b2addda5-770f-5a00-a8ee-1ad36152267e', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 11, 'information_ideas', 'inferences', 'medium', 'mc', 'Manuscript copies of a medieval medical text survive in twelve libraries. Eleven contain a chapter on eye surgery; the twelfth, the oldest surviving copy, does not, and its page numbering runs continuously across the point where the chapter would appear. This suggests that the chapter _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"was removed from the oldest copy after it was bound."},{"key":"B","text":"was added to the text after the oldest surviving copy was made."},{"key":"C","text":"was the most frequently consulted part of the work."},{"key":"D","text":"was written by a different author from the rest of the text."}]'::jsonb, 'B', null, 'Continuous page numbering shows nothing was cut out of the oldest copy, so the chapter''s absence there means it did not yet exist when that copy was made. Choice A is exactly what the unbroken numbering rules out.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('26ad5e0b-8f12-56e5-a79d-8aed959fda2f', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 12, 'information_ideas', 'evidence_textual', 'medium', 'mc', 'A researcher hypothesises that urban peregrine falcons hunt at night, using artificial light, whereas rural peregrines do not.', 'Which finding, if true, would most directly support the researcher''s hypothesis?', '[{"key":"A","text":"Urban peregrines nest on tall buildings at heights similar to their rural cliff sites."},{"key":"B","text":"Prey remains at urban nests include a high proportion of nocturnally migrating songbirds, which are largely absent from rural nests."},{"key":"C","text":"Urban peregrines raise slightly larger clutches than rural peregrines."},{"key":"D","text":"Artificial light levels in the study city have increased over the past two decades."}]'::jsonb, 'B', null, 'Nocturnal migrants in the urban diet but not the rural one is direct evidence that urban birds are catching prey that flies at night. Choice D establishes the opportunity for night hunting but shows no evidence that the falcons take it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('635a6512-8c36-59fe-aa9b-d9409a22dce8', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 13, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'The Voynich manuscript has resisted decipherment for a century. Statistical analyses show that its script has word-length distributions and entropy resembling natural language rather than random strings, yet no scholar has matched it to any known language, and no bilingual text has surfaced.', 'According to the text, what makes the manuscript''s script puzzling?', '[{"key":"A","text":"It uses characters that appear in no other historical document."},{"key":"B","text":"It behaves statistically like a real language while matching none."},{"key":"C","text":"It has been shown to be a random sequence of symbols."},{"key":"D","text":"It exists in only a single incomplete copy."}]'::jsonb, 'B', null, 'The passage contrasts language-like statistics with the failure to match any known language, and that tension is the puzzle. Choice C directly contradicts the statistical finding reported.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('91779c89-2303-5bc0-a9f9-b1b107b437b7', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 14, 'information_ideas', 'evidence_quantitative', 'hard', 'mc', 'A trial tested whether adding a legume cover crop raises maize yield. Across 40 plots, mean yield was 6.1 t/ha with the cover crop and 5.6 t/ha without, a difference of 0.5 t/ha with a 95 percent confidence interval of −0.2 to 1.2 t/ha.', 'Which choice best describes what the data indicate about the effect of the cover crop?', '[{"key":"A","text":"The cover crop reliably raises yield by about 0.5 t/ha."},{"key":"B","text":"The observed yield gain is consistent with no true effect, so the trial is not conclusive."},{"key":"C","text":"The cover crop reduces yield in most plots."},{"key":"D","text":"The sample of 40 plots is large enough to rule out chance."}]'::jsonb, 'B', null, 'Because the confidence interval spans zero, a true effect of nothing cannot be excluded, so the result is inconclusive despite the positive point estimate. Choice A is the classic error of reading the point estimate while ignoring the interval around it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0e5cc130-8495-5c24-ae07-cfee97c7c113', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 15, 'information_ideas', 'inferences', 'hard', 'mc', 'Modern beavers cannot fell trees more than about half a metre across. Fossil dams from the Pliocene, however, contain trunks nearly twice that diameter, and the beaver species present at the time was no larger than today''s. Researchers therefore propose that _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"the Pliocene trunks were incorporated after falling by other means, such as wind or flooding."},{"key":"B","text":"Pliocene beavers had substantially stronger jaws than modern beavers."},{"key":"C","text":"the fossil dams were built by a much larger, undiscovered species."},{"key":"D","text":"modern beavers avoid large trees only because of competition."}]'::jsonb, 'A', null, 'Since body size is held constant, the proposal must explain the large trunks without invoking bigger or stronger beavers, and scavenging already-fallen timber does exactly that. Choice C is ruled out by the statement that the beaver species of the period was no larger than today''s.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('131c06a2-f74a-57b7-a6a6-272b5b9b3226', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 16, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'The museum''s new wing, which opened in March, _______ three galleries devoted to textiles.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"contain"},{"key":"B","text":"containing"},{"key":"C","text":"contains"},{"key":"D","text":"to contain"}]'::jsonb, 'C', null, 'The singular subject ''wing'' needs the singular present-tense verb ''contains''; the relative clause between them does not change the subject. Choices B and D are non-finite forms that would leave the sentence without a main verb.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('957e4547-f635-5304-ab41-b0469303f4ce', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 17, 'standard_conventions', 'boundaries', 'easy', 'mc', 'After weeks of rehearsal in a borrowed hall _______ the quartet recorded the whole programme in a single afternoon.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":"; "},{"key":"C","text":": "},{"key":"D","text":" — and "}]'::jsonb, 'A', null, 'An introductory prepositional phrase is separated from the main clause by a comma. A semicolon or colon requires an independent clause before it, and the opening phrase has no subject or verb.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2ce3c304-6a0c-5de6-ab55-266c74476acd', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 18, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'Neither the two surveying teams nor the project geologist _______ able to explain the anomaly in the magnetic readings.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"were"},{"key":"B","text":"are"},{"key":"C","text":"have been"},{"key":"D","text":"was"}]'::jsonb, 'D', null, 'With ''neither...nor'', the verb agrees with the nearer subject, and ''the project geologist'' is singular, so ''was'' is correct. Choice A follows the plural ''teams'', which is the more distant subject and does not govern the verb here.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('45f79cb3-f396-5fec-a2de-1ca3aec69f9f', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 19, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The recipe calls for three ingredients that are hard to find outside the region _______ a bitter orange, a fermented pepper paste, and a dried river fish.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":": "},{"key":"B","text":"; "},{"key":"C","text":", and "},{"key":"D","text":" "}]'::jsonb, 'A', null, 'A colon introduces a list that follows a complete independent clause, which is the case here. A semicolon would require a full clause on both sides, and choice D would run the list into the clause with no punctuation at all.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('441a2faa-1164-5348-a5be-9c31ff5edd95', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 20, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'By the time the survey ship reached the trench, the autonomous submersible _______ four descents.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"completes"},{"key":"B","text":"had completed"},{"key":"C","text":"completing"},{"key":"D","text":"will complete"}]'::jsonb, 'B', null, 'The descents finished before the ship arrived, and both events are in the past, so the past perfect ''had completed'' marks the earlier action. Choice D puts a past-anchored sequence into the future.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1984f13d-9445-5ce8-a7ea-536ec615cf87', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 21, 'standard_conventions', 'boundaries', 'hard', 'mc', 'Chinua Achebe''s novel was published in 1958 _______ within a decade it had been translated into more than thirty languages.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":", and "},{"key":"C","text":" and, "},{"key":"D","text":"and "}]'::jsonb, 'B', null, 'Two independent clauses require a comma plus a coordinating conjunction, which choice B supplies. Choice A alone creates a comma splice, and choice D joins them with no punctuation, producing a run-on.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('287032f2-2100-56b5-ad9e-6db8206dc5c9', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 22, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'The committee praised the proposal for its clear budget, its realistic timetable, and _______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"because it involved the community."},{"key":"B","text":"its plan to involve the community."},{"key":"C","text":"that the community would be involved."},{"key":"D","text":"involving of the community in it."}]'::jsonb, 'B', null, 'The list already contains two possessive noun phrases, so the third item must take the same form for parallel structure. Choices A and C switch to subordinate clauses, breaking the pattern the first two items establish.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7c3cdcd7-5b91-51e1-ac5d-113a28e46b8b', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 23, 'expression_ideas', 'transitions', 'easy', 'mc', 'Aluminium is abundant in the earth''s crust. _______ it remained more valuable than gold until an electrolytic process for separating it was developed in 1886.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"For example,"},{"key":"B","text":"Even so,"},{"key":"C","text":"As a result,"},{"key":"D","text":"Likewise,"}]'::jsonb, 'B', null, 'Abundance would normally imply cheapness, so the high price is a surprising contrast requiring a concessive transition. ''As a result'' asserts the opposite causal relationship and makes the sentence illogical.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('99224f8d-8b52-5d96-a0b4-d12610e506f6', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 24, 'expression_ideas', 'rhetorical_synthesis', 'medium', 'mc', 'While researching, a student took these notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('86d090eb-eff3-548a-adc3-7a34987f8bd7', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 25, 'expression_ideas', 'transitions', 'medium', 'mc', 'The team assumed that the pottery had been made locally, since the clay matched nearby deposits. Chemical analysis of the temper, however, identified volcanic sand from an island 300 kilometres away. _______ the vessels were probably shaped elsewhere and traded in.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Nonetheless,"},{"key":"B","text":"Thus,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"Granted,"}]'::jsonb, 'B', null, 'The final sentence draws the conclusion that follows from the temper evidence, so a resultative transition is needed. ''Nonetheless'' would signal a reversal even though the sentence agrees with the evidence just presented.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('24b4557b-9580-5538-a757-ce86d6fc20a3', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 26, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching, a student took these notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fbe1bd3e-4099-5fdf-a44f-496dfd0e925f', '0a789449-0fd0-5581-a548-d3f35c5f13c4', 27, 'expression_ideas', 'transitions', 'hard', 'mc', 'Standard models predicted that the alloy would lose strength above 600°C, as its grain boundaries coarsened. In tests it held its strength to 850°C. _______ the boundaries were found to be pinned by nanoscale oxide particles that the models did not include.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Notably,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"That is because"},{"key":"D","text":"Similarly,"}]'::jsonb, 'C', null, 'The final sentence supplies the mechanism explaining the unexpected result, so an explicitly causal connector is required. ''Notably'' would merely flag the finding as interesting and would lose the explanatory link the sentence actually performs.') on conflict (id) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', '7dec74dc-2b56-5201-a48c-87b6ed7276b9', 3, 'Math — Module 1', 'math', 2100) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4eb049b6-97fc-5d40-acfd-cebb6881bf4e', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 1, 'algebra', 'linear_eq_one_var', 'easy', 'mc', null, 'If 3x + 7 = 25, what is the value of x?', '[{"key":"A","text":"4"},{"key":"B","text":"6"},{"key":"C","text":"8"},{"key":"D","text":"32/3"}]'::jsonb, 'B', null, 'Subtract 7 from both sides to get 3x = 18, then divide by 3 to get x = 6. Choice D comes from dividing 32 by 3 after adding 7 instead of subtracting it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('bda3212d-5e19-5414-adf0-361a397ff06e', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 2, 'algebra', 'linear_eq_two_var', 'easy', 'mc', null, 'A line in the xy-plane has slope 3 and passes through the point (0, −2). Which equation represents the line?', '[{"key":"A","text":"y = 3x − 2"},{"key":"B","text":"y = −2x + 3"},{"key":"C","text":"y = 3x + 2"},{"key":"D","text":"y = x/3 − 2"}]'::jsonb, 'A', null, 'Slope-intercept form is y = mx + b, and a point with x = 0 gives the y-intercept directly, so m = 3 and b = −2. Choice B swaps the slope and the intercept, a common mix-up when reading the point.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('24c4b8de-6c3c-50d8-a58e-29095f27bf5a', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 3, 'algebra', 'linear_eq_one_var', 'easy', 'spr', null, 'If 5(x − 2) = 35, what is the value of x?', null, '9', '["9.0"]'::jsonb, 'Divide both sides by 5 to get x − 2 = 7, then add 2 to get x = 9. Distributing first gives 5x − 10 = 35 and the same result; forgetting to distribute the 5 across the −2 is what produces 7.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a0494e5e-74a9-50b0-aa61-38625ced8c3d', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 4, 'advanced_math', 'equivalent_expressions', 'easy', 'mc', null, 'Which expression is equivalent to (x + 3)(x − 5)?', '[{"key":"A","text":"x² − 2x − 15"},{"key":"B","text":"x² + 2x − 15"},{"key":"C","text":"x² − 15"},{"key":"D","text":"x² − 2x + 15"}]'::jsonb, 'A', null, 'Expanding gives x² − 5x + 3x − 15 = x² − 2x − 15. Choice D keeps the constant positive, which would require both signs in the factors to match.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('153bca8a-0dd4-5f8a-a983-dc9de9b16d68', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 5, 'advanced_math', 'nonlinear_functions', 'easy', 'mc', null, 'If f(x) = x² − 4, what is the value of f(−3)?', '[{"key":"A","text":"−13"},{"key":"B","text":"5"},{"key":"C","text":"13"},{"key":"D","text":"−5"}]'::jsonb, 'B', null, 'Squaring −3 gives 9, and 9 − 4 = 5. Choice A results from computing −(3²) − 4, which drops the parentheses around the negative input.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('34f6a87a-e323-5038-a3f2-8f8f0f63ac04', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 6, 'psda', 'percentages', 'easy', 'mc', null, 'A jacket priced at $80 is increased in price by 15 percent. What is the new price?', '[{"key":"A","text":"$88.00"},{"key":"B","text":"$92.00"},{"key":"C","text":"$95.00"},{"key":"D","text":"$120.00"}]'::jsonb, 'B', null, 'Fifteen percent of 80 is 12, so the new price is 80 + 12 = $92. Choice A uses 10 percent instead of 15.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f9e159fd-9808-5c33-a4d8-7a1d81b29df7', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 7, 'geometry_trig', 'lines_angles_triangles', 'easy', 'mc', null, 'In a triangle, two of the interior angles measure 40° and 65°. What is the measure of the third angle?', '[{"key":"A","text":"65°"},{"key":"B","text":"75°"},{"key":"C","text":"85°"},{"key":"D","text":"105°"}]'::jsonb, 'B', null, 'The interior angles of a triangle sum to 180°, so the third angle is 180 − 40 − 65 = 75°. Choice D is the sum of the two given angles rather than the remainder.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('588dfe7a-2bd6-5745-aece-981be8d2ed9a', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 8, 'algebra', 'linear_functions', 'medium', 'mc', null, 'The linear function f satisfies f(2) = 11 and f(5) = 23. What is the value of f(8)?', '[{"key":"A","text":"29"},{"key":"B","text":"31"},{"key":"C","text":"35"},{"key":"D","text":"38"}]'::jsonb, 'C', null, 'The slope is (23 − 11)/(5 − 2) = 4, so each unit increase in x adds 4, and from x = 5 to x = 8 the value rises by 12 to 35. Choice A comes from adding only a single step of 4 twice instead of three times.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9cfd77d9-b2f0-56af-a05e-6ffabbd8812b', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 9, 'algebra', 'systems_two_linear', 'medium', 'mc', null, 'If 2x + y = 11 and x − y = 1, what is the value of y?', '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]'::jsonb, 'B', null, 'Adding the equations eliminates y: 3x = 12, so x = 4, and substituting into x − y = 1 gives y = 3. Choice C is the value of x, which is the most common slip when the question asks for the other variable.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('db61e3cd-260e-5495-ac9b-20b53ee35c50', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 10, 'algebra', 'linear_inequalities', 'medium', 'spr', null, 'What is the greatest integer value of x that satisfies 4x + 9 ≤ 33?', null, '6', '["6.0"]'::jsonb, 'Subtracting 9 gives 4x ≤ 24, so x ≤ 6, and 6 itself satisfies the inequality because the sign is ''less than or equal to''. Answering 5 treats the inequality as strict.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('69cb4eb2-0e60-550f-a68b-6099fc1b3330', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 11, 'advanced_math', 'nonlinear_eq_systems', 'medium', 'mc', null, 'What is the larger solution to x² − 7x + 12 = 0?', '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"6"}]'::jsonb, 'C', null, 'The expression factors as (x − 3)(x − 4), so the solutions are 3 and 4 and the larger is 4. Choice B is the smaller root, which is the answer to a different question.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fec9abd2-fd1c-564d-a1ea-58fd87193908', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 12, 'advanced_math', 'equivalent_expressions', 'medium', 'spr', null, 'If 2^(x + 1) = 32, what is the value of x?', null, '4', '["4.0"]'::jsonb, 'Since 32 = 2⁵, the exponents must match: x + 1 = 5, so x = 4. Answering 5 stops one step early by solving for the exponent rather than for x.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d8de6952-a756-55dd-a9dc-faf2eb9c4086', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 13, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The function g is defined by g(x) = (x − 4)² + 2. What is the minimum value of g?', '[{"key":"A","text":"−4"},{"key":"B","text":"0"},{"key":"C","text":"2"},{"key":"D","text":"4"}]'::jsonb, 'C', null, 'A squared term is never negative, so g is smallest when (x − 4)² = 0, which happens at x = 4 and leaves g = 2. Choice D reports the x-value at which the minimum occurs rather than the minimum value itself.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('36c48064-5a16-56b8-ab43-9fe149ac4e7c', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 14, 'psda', 'ratios_rates_proportions', 'medium', 'spr', null, 'A dough recipe uses flour and water in a ratio of 3 to 5 by weight. If a baker uses 18 kilograms of flour, how many kilograms of water are needed?', null, '30', '["30.0"]'::jsonb, 'Eighteen kilograms of flour is 6 times the 3 parts in the ratio, so the water is 6 × 5 = 30 kilograms. Answering 10.8 comes from applying the ratio in reverse, treating flour as the larger share.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4f108344-9fd3-5054-afc6-341e0585d95a', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 15, 'geometry_trig', 'circles', 'medium', 'spr', null, 'A circle has an area of 36π square centimetres. What is its radius, in centimetres?', null, '6', '["6.0"]'::jsonb, 'Area is πr², so r² = 36 and r = 6. Answering 18 halves the area''s coefficient as though the formula were linear in r.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a11c6232-495e-5ca2-a645-18c3122c92b0', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 16, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'The system 3x + ky = 7 and 6x + 8y = 5 has no solution. What is the value of k?', '[{"key":"A","text":"2"},{"key":"B","text":"4"},{"key":"C","text":"8"},{"key":"D","text":"16"}]'::jsonb, 'B', null, 'No solution means the lines are parallel, so the coefficients must be proportional: 6/3 = 2, and k must satisfy 8/k = 2, giving k = 4. The constants 7 and 5 are not in that ratio, which is what makes the system inconsistent rather than identical.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('df2db611-c3ef-5b4d-aa54-8bed068b56e1', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 17, 'algebra', 'linear_eq_one_var', 'hard', 'mc', null, 'A car service charges a fixed fee of $3.50 plus $1.75 for each mile travelled. What is the greatest whole number of miles a rider can travel for at most $30.00?', '[{"key":"A","text":"14"},{"key":"B","text":"15"},{"key":"C","text":"16"},{"key":"D","text":"17"}]'::jsonb, 'B', null, 'Solve 3.50 + 1.75m ≤ 30, so 1.75m ≤ 26.50 and m ≤ 15.14, and the greatest whole number is 15. Choice C comes from rounding 15.14 up, but a 16th mile would push the fare past the $30 limit.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('15e661a2-57c6-5859-a497-671533ca34a0', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 18, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'mc', null, 'The equation x² + bx + 49 = 0, where b is a positive constant, has exactly one real solution. What is the value of b?', '[{"key":"A","text":"7"},{"key":"B","text":"14"},{"key":"C","text":"49"},{"key":"D","text":"98"}]'::jsonb, 'B', null, 'Exactly one real solution means the discriminant is zero: b² − 4(1)(49) = 0, so b² = 196 and b = 14 since b is positive. Choice A takes the square root of 49 instead of solving the discriminant condition.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3087e191-ac6c-5507-a29c-09d64cf1e2df', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 19, 'advanced_math', 'equivalent_expressions', 'hard', 'spr', null, 'If (x² − 9)/(x − 3) = 12 and x ≠ 3, what is the value of x?', null, '9', '["9.0"]'::jsonb, 'Factoring the numerator as (x − 3)(x + 3) and cancelling the common factor leaves x + 3 = 12, so x = 9. Cross-multiplying without factoring leads to a quadratic whose extraneous root is the excluded value x = 3.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f0210b3f-bb1d-5b0e-ac79-19b2f57356e1', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 20, 'advanced_math', 'nonlinear_functions', 'hard', 'mc', null, 'A bacterial culture starts with 400 cells and doubles every 6 hours. Which function gives the number of cells after t hours?', '[{"key":"A","text":"P(t) = 400 · 2^(6t)"},{"key":"B","text":"P(t) = 400 · 2^(t/6)"},{"key":"C","text":"P(t) = 400 · 6^(t/2)"},{"key":"D","text":"P(t) = 400 + 2t/6"}]'::jsonb, 'B', null, 'Each doubling period is 6 hours, so the number of doublings after t hours is t/6 and the factor is 2^(t/6). Choice A multiplies rather than divides by 6, which would make the culture double every 10 minutes.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a08a930b-2437-593b-a286-e0eda69eb073', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 21, 'psda', 'sample_stats_moe', 'hard', 'mc', null, 'A random sample of 900 residents found that 46 percent support a proposal, with a margin of error of 3 percentage points at the 95 percent confidence level. Which conclusion is best supported?', '[{"key":"A","text":"Exactly 46 percent of all residents support the proposal."},{"key":"B","text":"It is plausible that support among all residents is between 43 and 49 percent."},{"key":"C","text":"A majority of residents support the proposal."},{"key":"D","text":"Increasing the sample size would necessarily raise the reported support."}]'::jsonb, 'B', null, 'A margin of error defines an interval of plausible values for the population figure, here 46 ± 3 percent. Choice C is wrong because the entire interval lies below 50 percent, and choice A treats a sample estimate as an exact population value.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a523af0a-700e-51cf-a7f9-8628b2bb9391', '7c7dff4c-0cf0-5c3e-a7a8-16a26e774088', 22, 'geometry_trig', 'right_triangles_trig', 'hard', 'mc', null, 'In right triangle ABC, angle C measures 90°, sin A = 0.6, and the hypotenuse AB has length 20. What is the length of BC?', '[{"key":"A","text":"8"},{"key":"B","text":"12"},{"key":"C","text":"16"},{"key":"D","text":"20"}]'::jsonb, 'B', null, 'Side BC is opposite angle A, and sin A = opposite/hypotenuse, so BC = 0.6 × 20 = 12. Choice C is AC, the adjacent side, found from cos A = 0.8.') on conflict (id) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('06ef4fcf-7a79-590a-a0e9-aea7aa69898a', '7dec74dc-2b56-5201-a48c-87b6ed7276b9', 4, 'Math — Module 2', 'math', 2100) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3a14ef6b-8c53-5374-a76d-271785f2bda6', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 1, 'algebra', 'linear_eq_one_var', 'easy', 'mc', null, 'If 7 − 2x = 1, what is the value of x?', '[{"key":"A","text":"−3"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"−4"}]'::jsonb, 'B', null, 'Subtracting 7 gives −2x = −6, and dividing by −2 gives x = 3. Choice A drops one of the two negative signs when dividing.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0c92dd78-3677-5601-a0d6-f9949a62c95f', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 2, 'algebra', 'linear_functions', 'easy', 'mc', null, 'A phone plan costs $12 per month plus $0.05 per minute of calls. Which function gives the monthly cost C, in dollars, for m minutes?', '[{"key":"A","text":"C(m) = 12m + 0.05"},{"key":"B","text":"C(m) = 0.05m + 12"},{"key":"C","text":"C(m) = 12.05m"},{"key":"D","text":"C(m) = 12 + 5m"}]'::jsonb, 'B', null, 'The fixed $12 is the constant term and the per-minute charge multiplies the variable, giving C(m) = 0.05m + 12. Choice A swaps the roles of the fixed fee and the rate.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9468ee5a-3278-5e85-a57f-b8bbc684d767', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 3, 'algebra', 'linear_eq_two_var', 'easy', 'spr', null, 'The line y = 2x + b passes through the point (3, 10). What is the value of b?', null, '4', '["4.0"]'::jsonb, 'Substituting gives 10 = 2(3) + b, so b = 10 − 6 = 4. Answering 16 adds 6 instead of subtracting it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a0c313cc-6f3a-5240-a5b2-22652fdeb053', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 4, 'advanced_math', 'equivalent_expressions', 'easy', 'mc', null, 'Which expression is equivalent to 4x² + 12x?', '[{"key":"A","text":"4x(x + 3)"},{"key":"B","text":"4(x² + 12x)"},{"key":"C","text":"x(4x + 12x)"},{"key":"D","text":"4x(x + 12)"}]'::jsonb, 'A', null, 'The greatest common factor of both terms is 4x, and dividing gives x + 3, so the factored form is 4x(x + 3). Choice B factors only the 4 out of the first term and leaves the second unchanged.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fee717e4-8d69-5061-a991-5ba8cdf0dcb7', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 5, 'advanced_math', 'nonlinear_functions', 'easy', 'mc', null, 'If f(x) = 2x² + 1, what is f(3) − f(1)?', '[{"key":"A","text":"8"},{"key":"B","text":"12"},{"key":"C","text":"16"},{"key":"D","text":"19"}]'::jsonb, 'C', null, 'f(3) = 2(9) + 1 = 19 and f(1) = 2(1) + 1 = 3, so the difference is 16. Choice D is f(3) alone, which forgets to subtract.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8e15a5b1-41da-53bc-a133-45c98994d6e2', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 6, 'psda', 'probability', 'easy', 'mc', null, 'A bag contains 5 red, 7 blue, and 8 green marbles. If one marble is drawn at random, what is the probability that it is blue?', '[{"key":"A","text":"7/20"},{"key":"B","text":"7/13"},{"key":"C","text":"1/3"},{"key":"D","text":"13/20"}]'::jsonb, 'A', null, 'There are 20 marbles in total and 7 are blue, so the probability is 7/20. Choice B leaves the blue marbles out of the denominator, comparing blue to non-blue instead of to the whole.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7b166254-a972-5ded-a2ad-6eaf9fdd0864', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 7, 'geometry_trig', 'area_volume', 'easy', 'mc', null, 'A rectangular tank measures 3 m by 4 m by 2 m. What is its volume, in cubic metres?', '[{"key":"A","text":"9"},{"key":"B","text":"12"},{"key":"C","text":"24"},{"key":"D","text":"48"}]'::jsonb, 'C', null, 'Volume is the product of the three dimensions: 3 × 4 × 2 = 24 cubic metres. Choice B multiplies only the base dimensions, giving area rather than volume.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('21953f9b-e3b0-5905-a9e2-7cdf1b19e985', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 8, 'algebra', 'linear_inequalities', 'medium', 'mc', null, 'Which value of x satisfies −3x + 5 > 14?', '[{"key":"A","text":"−4"},{"key":"B","text":"−3"},{"key":"C","text":"0"},{"key":"D","text":"3"}]'::jsonb, 'A', null, 'Subtracting 5 gives −3x > 9, and dividing by −3 reverses the inequality to x < −3, so only −4 works. Choice B fails because x = −3 gives exactly 14, not more than 14.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('32cadadb-8e08-5c87-ae85-5c4e16e44bc6', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 9, 'algebra', 'systems_two_linear', 'medium', 'spr', null, 'At a stall, 2 mangoes and 3 oranges cost 130 birr, and 2 mangoes and 1 orange cost 90 birr. What is the cost, in birr, of one orange?', null, '20', '["20.0"]'::jsonb, 'Subtracting the second equation from the first eliminates the mangoes: 2 oranges cost 40 birr, so one orange costs 20. Substituting back gives a mango at 35 birr, which checks against both equations.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('06aad841-c794-5701-a1de-c530dce354ac', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 10, 'algebra', 'linear_functions', 'medium', 'mc', null, 'The function h is linear, h(0) = −5, and h(4) = 7. What is the slope of the graph of h?', '[{"key":"A","text":"1/3"},{"key":"B","text":"3"},{"key":"C","text":"12"},{"key":"D","text":"−3"}]'::jsonb, 'B', null, 'Slope is the change in output over the change in input: (7 − (−5))/(4 − 0) = 12/4 = 3. Choice C reports the change in output alone without dividing by the change in input.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e4049bc0-0ce9-570e-aff9-8ae417460fe2', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 11, 'advanced_math', 'nonlinear_eq_systems', 'medium', 'mc', null, 'What are the solutions to x² = 6x?', '[{"key":"A","text":"x = 6 only"},{"key":"B","text":"x = 0 and x = 6"},{"key":"C","text":"x = 0 only"},{"key":"D","text":"x = ±√6"}]'::jsonb, 'B', null, 'Rewriting as x² − 6x = 0 and factoring gives x(x − 6) = 0, so x = 0 or x = 6. Choice A is the result of dividing both sides by x, which silently discards the solution x = 0.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('44d6cece-478f-5550-a26d-7eba4c7565ef', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 12, 'advanced_math', 'equivalent_expressions', 'medium', 'spr', null, 'If √(x + 7) = 5, what is the value of x?', null, '18', '["18.0"]'::jsonb, 'Squaring both sides gives x + 7 = 25, so x = 18, and checking confirms √25 = 5. Answering 32 comes from adding 7 after squaring instead of subtracting it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fc5a127d-6953-526a-a123-ed99dd25d4f8', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 13, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The graph of y = x² − 6x + 5 crosses the x-axis at two points. What is the distance between them?', '[{"key":"A","text":"1"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}]'::jsonb, 'B', null, 'Factoring gives (x − 1)(x − 5), so the intercepts are at x = 1 and x = 5 and the distance is 4. Choice C is one of the intercepts rather than the gap between them.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2c0dd134-df83-5b49-a4d1-a90119e821dd', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 14, 'psda', 'one_var_data', 'medium', 'spr', null, 'The list of values 4, 7, 7, 9, 13 has a mean of m and a median of d. What is the value of m − d?', null, '1', '["1.0"]'::jsonb, 'The five values sum to 40, so the mean is 8, and the middle value of the ordered list is 7, so m − d = 1. Answering 0 usually means the median was computed as the mean of the two central values, which applies only to an even-sized list.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('04a38d8a-ef1d-505b-ad33-f0788c651538', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 15, 'geometry_trig', 'right_triangles_trig', 'medium', 'spr', null, 'A right triangle has legs of length 9 and 12. What is the length of its hypotenuse?', null, '15', '["15.0"]'::jsonb, 'By the Pythagorean theorem, 9² + 12² = 81 + 144 = 225, and √225 = 15. Answering 21 adds the legs instead of using their squares.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1973838c-caf6-50fe-ad09-1b6b06a34651', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 16, 'algebra', 'linear_eq_two_var', 'hard', 'mc', null, 'In the xy-plane, line ℓ is perpendicular to the line 2x + 3y = 12 and passes through the origin. Which equation represents line ℓ?', '[{"key":"A","text":"y = (3/2)x"},{"key":"B","text":"y = (−2/3)x"},{"key":"C","text":"y = (−3/2)x"},{"key":"D","text":"y = (2/3)x"}]'::jsonb, 'A', null, 'Rewriting gives y = (−2/3)x + 4, so the perpendicular slope is the negative reciprocal, 3/2, and passing through the origin makes the intercept 0. Choice B repeats the original slope instead of inverting and negating it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2d8186bf-9d4f-548d-a9da-47bc9eb4901e', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 17, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'A chemist mixes a 20 percent acid solution with a 50 percent acid solution to make 30 litres of a 30 percent solution. How many litres of the 50 percent solution are used?', '[{"key":"A","text":"8"},{"key":"B","text":"10"},{"key":"C","text":"12"},{"key":"D","text":"20"}]'::jsonb, 'B', null, 'If x litres are 50 percent, then 0.5x + 0.2(30 − x) = 0.3(30) = 9, giving 0.3x = 3 and x = 10. Choice D is the volume of the weaker solution, which is 30 − 10 = 20 litres.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('15b25625-b908-596a-a5f6-17e5a7f80391', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 18, 'advanced_math', 'nonlinear_functions', 'hard', 'spr', null, 'A ball is thrown upward and its height in metres after t seconds is h(t) = −5t² + 20t. After how many seconds does it return to the ground?', null, '4', '["4.0"]'::jsonb, 'Setting h(t) = 0 gives −5t(t − 4) = 0, so t = 0 at launch and t = 4 on landing. Answering 2 gives the time of maximum height, which is halfway through the flight.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7c1a15e6-a680-5820-a259-4d74d8865186', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 19, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'mc', null, 'The system y = x² − 3 and y = 2x has how many real solutions?', '[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"Infinitely many"}]'::jsonb, 'C', null, 'Setting the expressions equal gives x² − 2x − 3 = 0, whose discriminant is 4 + 12 = 16 > 0, so there are two distinct real solutions (x = −1 and x = 3). Choice B would require the discriminant to be exactly zero, meaning the line is tangent to the parabola.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('acaa644b-ea0a-5830-ab69-fa3ad3faf250', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 20, 'advanced_math', 'equivalent_expressions', 'hard', 'mc', null, 'Which expression is equivalent to (3x²y³)² / (9x y⁴)?', '[{"key":"A","text":"x³y²"},{"key":"B","text":"x³y²/3"},{"key":"C","text":"9x³y²"},{"key":"D","text":"x⁴y²"}]'::jsonb, 'A', null, 'The numerator squares to 9x⁴y⁶, and dividing by 9xy⁴ cancels the 9 and subtracts exponents to give x³y². Choice C forgets that the 9 in the denominator cancels the 9 produced by squaring the 3.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('992114bb-50cf-58c8-afe0-7f8b8768de71', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 21, 'psda', 'percentages', 'hard', 'mc', null, 'After a 20 percent discount, a bicycle sells for $340. What was its price before the discount?', '[{"key":"A","text":"$408"},{"key":"B","text":"$408.50"},{"key":"C","text":"$425"},{"key":"D","text":"$680"}]'::jsonb, 'C', null, 'The sale price is 80 percent of the original, so the original is 340 ÷ 0.8 = $425. Choice A adds 20 percent to the sale price, which is the classic error because 20 percent of the smaller number is not the same amount as 20 percent of the larger one.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cf1f399a-d274-503c-a131-a6ef1ad96565', '06ef4fcf-7a79-590a-a0e9-aea7aa69898a', 22, 'geometry_trig', 'circles', 'hard', 'mc', null, 'A central angle of 60° in a circle of radius 9 cuts off an arc. What is the length of that arc?', '[{"key":"A","text":"3π"},{"key":"B","text":"6π"},{"key":"C","text":"9π"},{"key":"D","text":"18π"}]'::jsonb, 'A', null, 'A 60° angle is one sixth of the circle, and the circumference is 2π(9) = 18π, so the arc is 18π/6 = 3π. Choice B applies the fraction to the diameter-based value incorrectly by taking one third instead of one sixth.') on conflict (id) do nothing;
